package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(num()), int(num())
	start, length := make([]int64, n), make([]int64, n)
	for j := 0; j < n; j++ {
		start[j], length[j] = num(), num()
	}
	bytes := make([]int64, m)
	var top int64
	for i := range bytes {
		bytes[i] = num()
		top = max(top, bytes[i])
	}
	seen, done := make([]bool, top+1), make([]bool, n)
	count := 0
	out := []byte{}
	for i, b := range bytes {
		seen[b] = true
		// A segment completes once every offset of [start, start + length) has arrived.
		for j := 0; j < n; j++ {
			if done[j] {
				continue
			}
			all := true
			for x := start[j]; x < start[j]+length[j] && all; x++ {
				all = x >= 0 && x <= top && seen[x]
			}
			if all {
				done[j] = true
				count++
			}
		}
		if i > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, int64(count), 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
